export function buildKiosk() {
  const kiosk = new THREE.Group();
  kiosk.name = 'kiosk';
  kiosk.userData = { version: 2, sku: 'KSK-01' };

  // Box counter at origin
  const counter = new THREE.Mesh(
    new THREE.BoxGeometry(2, 1, 0.8),
    new THREE.MeshStandardMaterial({ color: 0x888888 })
  );
  counter.name = 'counter';
  counter.position.set(0, 0.5, 0);
  kiosk.add(counter);

  // Cylinder stool, offset and rotated about y
  const stool = new THREE.Mesh(
    new THREE.CylinderGeometry(0.25, 0.25, 0.6, 24),
    new THREE.MeshStandardMaterial({ color: 0x444444 })
  );
  stool.name = 'stool';
  stool.position.set(1.2, 0.3, 0);
  stool.rotation.y = 0.3;
  kiosk.add(stool);

  // Sign plane at height 2
  const sign = new THREE.Mesh(
    new THREE.PlaneGeometry(1.5, 0.5),
    new THREE.MeshStandardMaterial({ color: 0xff6633, roughness: 0.4 })
  );
  sign.name = 'sign';
  sign.position.set(0, 2, 0);
  kiosk.add(sign);

  return kiosk;
}
