import * as THREE from 'three';
import { buildKiosk } from '../src/kiosk.js';
import { serialize, revive } from '../src/roundtrip.js';

const EPS = 1e-9;

/** Recursively strip generated uuid fields so JSON comparisons are stable. */
function stripUuids(value) {
  if (Array.isArray(value)) return value.map(stripUuids);
  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      if (k === 'uuid') continue;
      out[k] = stripUuids(v);
    }
    return out;
  }
  return value;
}

describe('kiosk scene serialization round-trip', () => {
  it('revive(serialize(k)) preserves structure, transforms, material, and userData', () => {
    const original = buildKiosk();
    const revived = revive(serialize(original));

    expect(revived).toBeInstanceOf(THREE.Group);
    expect(revived.name).toBe('kiosk');
    expect(revived.children).toHaveLength(original.children.length);
    expect(revived.children).toHaveLength(3);

    for (let i = 0; i < original.children.length; i++) {
      const a = original.children[i];
      const b = revived.children[i];
      expect(b.name).toBe(a.name);

      // position / rotation / scale within 1e-9
      expect(b.position.x).toBeCloseTo(a.position.x, 12);
      expect(b.position.y).toBeCloseTo(a.position.y, 12);
      expect(b.position.z).toBeCloseTo(a.position.z, 12);
      expect(b.rotation.x).toBeCloseTo(a.rotation.x, 12);
      expect(b.rotation.y).toBeCloseTo(a.rotation.y, 12);
      expect(b.rotation.z).toBeCloseTo(a.rotation.z, 12);
      expect(b.scale.x).toBeCloseTo(a.scale.x, 12);
      expect(b.scale.y).toBeCloseTo(a.scale.y, 12);
      expect(b.scale.z).toBeCloseTo(a.scale.z, 12);
    }

    // Stool placement: (1.2, 0, ...) footprint with 0.3 rad y rotation
    const stool = revived.getObjectByName('stool');
    expect(stool.position.x).toBeCloseTo(1.2, 12);
    expect(stool.position.y).toBeCloseTo(0, 12);
    expect(stool.rotation.y).toBeCloseTo(0.3, 12);

    // Sign plane at height 2 with the specified material
    const sign = revived.getObjectByName('sign');
    expect(sign.position.y).toBeCloseTo(2, 12);
    const mat = sign.material;
    expect(mat).toBeInstanceOf(THREE.MeshStandardMaterial);
    expect(mat.color.getHex()).toBe(0xff6633);
    expect(mat.roughness).toBeCloseTo(0.4, 12);

    // userData deep equality
    expect(revived.userData).toEqual({ version: 2, sku: 'KSK-01' });
  });

  it('a second round-trip is a stable fixed point of the JSON (ignoring uuids)', () => {
    const k = buildKiosk();
    const json1 = serialize(k);
    const json2 = serialize(revive(json1));

    expect(stripUuids(json2)).toEqual(stripUuids(json1));
  });
});
"})
